// Audio timeline: music + SFX stems (generated by ../scripts/make_audio.py from the
// same storyboard.json) and one optional voice recording per dialogue line.
import {ALL_LINES, FPS} from '../data/storyboard';
import manifest from './voice-manifest.json';
import {clamp, smooth} from '../lib/anim';

export const MUSIC_SRC = 'audio/music.wav';
export const SFX_SRC = 'audio/sfx.wav';
export const MUSIC_LEVEL = 0.75;
/** Music level while Loli speaks (only applied when a recording exists for that line). */
export const MUSIC_DUCKED = 0.22;
const DUCK_RAMP = 0.25; // s

type VoiceEntry = {file: string; duration: number; env: number[]};
const VOICE = (manifest as {lines: Record<string, VoiceEntry>}).lines;

export const voiceFor = (lineId: string): VoiceEntry | undefined => VOICE[lineId];

export const VOICE_CUES = ALL_LINES.map((l) => ({...l, voice: voiceFor(l.id)}));

/** Music volume at absolute time t: ducks smoothly under every recorded line. */
export const musicVolume = (t: number) => {
  let duck = 0;
  for (const c of VOICE_CUES) {
    if (!c.voice) continue;
    const end = c.absFrom + c.voice.duration;
    const inAmt = smooth((t - (c.absFrom - DUCK_RAMP)) / DUCK_RAMP);
    const outAmt = 1 - smooth((t - end) / DUCK_RAMP);
    duck = Math.max(duck, Math.min(inAmt, outAmt));
  }
  return MUSIC_LEVEL + (MUSIC_DUCKED - MUSIC_LEVEL) * duck;
};

/** 0..1 "how much Loli is talking" at absolute time t. Uses the recording's
 *  per-frame loudness envelope when available, else a syllable-rhythm placeholder
 *  inside the scripted dialogue window. */
export const speechLevel = (t: number) => {
  for (const c of VOICE_CUES) {
    if (c.voice) {
      const i = Math.floor((t - c.absFrom) * FPS);
      if (i >= 0 && i < c.voice.env.length) return c.voice.env[i];
      continue;
    }
    if (t >= c.absFrom && t < c.absTo) {
      const lt = t - c.absFrom;
      const edge = smooth(lt / 0.15) * smooth((c.absTo - t) / 0.15);
      const syll = Math.abs(Math.sin(lt * 12.5)) * (0.6 + 0.4 * Math.sin(lt * 3.3));
      return clamp(syll) * edge;
    }
  }
  return 0;
};
